def f(g):
    H,W=len(g),len(g[0])
    from collections import Counter
    vals=Counter(x for r in g for x in r)
    bg=vals.most_common(1)[0][0]
    # marker color = color whose cells are scattered (not forming the big cluster)
    # cluster = connected component of non-bg cells with max size
    cells=[(r,c) for r in range(H) for c in range(W) if g[r][c]!=bg]
    seen=set(); comps=[]
    for s in cells:
        if s in seen: continue
        st=[s]; comp=set()
        while st:
            r,c=st.pop()
            if (r,c) in comp: continue
            comp.add((r,c))
            for dr in(-1,0,1):
                for dc in(-1,0,1):
                    p=(r+dr,c+dc)
                    if p in cells and p not in comp: st.append(p)
        seen|=comp; comps.append(comp)
    block=max(comps,key=len)
    markers=[p for p in cells if p not in block]
    rs=[r for r,c in block]; cs=[c for r,c in block]
    r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
    pat=[[g[r][c] for c in range(c0,c1+1)] for r in range(r0,r1+1)]
    ph,pw=len(pat),len(pat[0]); orr,occ=ph//2,pw//2
    out=[row[:] for row in g]
    for (mr,mc) in markers:
        for i in range(ph):
            for j in range(pw):
                r,c=mr-orr+i, mc-occ+j
                if 0<=r<H and 0<=c<W: out[r][c]=pat[i][j]
    return out

